// Fim dos Tempos · Arco 2 · Lendas Urbanas e Linhas Narrativas · gerado por a2-lendas-linhas.js
const DADOS = {"lendas":[{"k":"vampiros","nome":"Os Vampiros de Pensamentos","texto":["Existem criaturas invisíveis que se alimentam de nossos pensamentos e emoções. Elas podem comer qualquer coisa que passe em nossa mente, mas preferem sentimentos fortes e pensamentos importantes.","Os nobres conhecem essas criaturas, mas não fazem nada contra elas porque são úteis. Quando elas devoram nossas emoções mais fortes, não conseguimos sentir ódio dos nobres. Quando elas sugam nossos pensamentos mais importantes, não conseguimos planejar ou fazer descobertas.","A única coisa que bloqueia os vampiros de pensamentos são metais preciosos — por isso os nobres usam coroas nas cabeças. Se uma dessas criaturas nos nota, o melhor é não se deixar levar por nenhum sentimento muito forte, nem pensar em nada muito complicado, até conseguir a proteção de uma coroa ou um elmo feito de ouro ou outro metal precioso."],"subtexto":"Alguns valkarianos notam que aventureiros e até vilões estão \"se acomodando\" e deixando de lado as atividades e emoções extremas. É efeito da Escola de Etiqueta e Bom Comportamento de Madame Margebell, que resulta na vizinhança pacata demais de Stremtol.","dica":"Aventura 1"},{"k":"serva","nome":"A Serva e o Bardo","texto":["É bom ter cuidado com a música que seus filhos, familiares e até servos escutam. Hoje em dia, bardos de todos os tipos ficam famosos em Valkaria e as pessoas se tornam tão obcecadas pela música que esquecem de todo o resto.","Certa vez uma serva de uma família nobre recebeu permissão para ir a uma taverna. Ficou a noite toda ouvindo os bardos. No dia seguinte, estava tão fascinada pela música que continuou dançando e cantando enquanto trabalhava. Seus deveres naquele dia eram preparar o jantar e ninar o filho de seus senhores. Distraída desse jeito, não percebeu quando colocou um faisão cru no berço e a criança no forno...","Infelizmente, até hoje algumas pessoas acham que uma música vale mais que uma vida."],"subtexto":"As músicas dos bardos que se apresentam na Terceira Opção e em tavernas parecidas estão espalhando fúria e loucura.","dica":"Aventura 4"},{"k":"megan","nome":"Megan Miserável","texto":["A inveja de algumas pessoas dura até depois da morte.","Megan era uma plebeia que tinha muita inveja das roupas e joias que as nobres usavam. Ela ficou tão consumida pela inveja que não conseguiu mais trabalhar e caiu na pobreza. A última coisa que Megan vendeu foi seu espelho, onde ficava se admirando o dia inteiro, imaginando-se com os vestidos e adornos das nobres. Ela morreu de fome e frio, sozinha, enquanto se olhava no espelho.","Hoje em dia, se você ficar na frente de um espelho e falar \"Megan Miserável\" cinco vezes, o fantasma de Megan aparece e leva você para dentro do espelho. Alguns dizem que isso só funciona se você for nobre, ou se estiver usando joias, ou se estiver dentro de um palácio."],"subtexto":"Reflete a boataria sobre os nobres raptados e substituídos no Baile da Primavera. A história real não tem nada a ver com espelhos, mas esse elemento representa a sensação de que os jovens nobres são as vítimas, especialmente quando estão arrumados para uma festa.","dica":"Aventura 6"},{"k":"praga","nome":"Os Doentes da Praga","texto":["Todos sabem que a Praga Coral foi criada por humanos para se livrar dos orcs no antigo reino de Lomatubar. O que poucos sabem é que existe uma forma muito fácil de transmitir a Praga Coral: basta ter um pedaço da \"casca\" que as vítimas da Praga adquirem e transformá-la em pó. Uma mera pitada desse pó em qualquer comida ou bebida é suficiente para contaminar com a Praga Coral.","Existem verdadeiros exércitos de vilões insanos espalhando a Praga Coral, principalmente para crianças, em tendas de petiscos e refrescos nas ruas e nos mercados. Outros loucos deixam agulhas infectadas com a Praga Coral escondidas nas arquibancadas da Arena Imperial, nos bancos de apresentações teatrais e até mesmo nas cadeiras de tavernas.","Se, ao sentar, você for picado por uma dessas agulhas, está contaminado para sempre. Muitas vezes o culpado fica por perto, esperando para ver o rosto de sua vítima."],"subtexto":"O contexto real não está na praga, mas nos \"exércitos de vilões insanos\" que fazem maldade sem ganhar nada, só por sadismo. Os valkarianos notam que as pessoas à sua volta ficam mais violentas, cruéis e perigosas sem motivo. É efeito do plano de Ghorskander (os Imagodutos).","dica":"a trama geral de Ghorskander (os Imagodutos)"},{"k":"golem","nome":"O Golem Errado","texto":["Havia em Valkaria um mago especialista em fabricar golens e encantar objetos. Ele tinha muitos golens e muitos itens mágicos em sua torre. Um dia o mago foi viajar e sua torre foi invadida por um casal de jovens ladrões. Eles sabiam que não podiam levar muita coisa, então examinaram os golens e os itens. Achavam que, se cada um levasse apenas um item, o mago não daria falta.","A moça logo notou um golem enorme e vistoso, segurando um martelo. Tirou o martelo das mãos do golem e decidiu levá-lo. O rapaz viu que o golem também tinha uma espada muito bonita. Quase pôs as mãos nela, mas achou que levar uma arma era arriscado demais. Afastou-se daquele golem e escolheu um singelo anel mágico.","Os dois estavam tão confiantes que, em vez de fugir logo, decidiram dormir na própria torre. De manhã, o rapaz acordou para descobrir sua namorada morta, com a cabeça esmagada. Olhou para cima e viu o tal golem, com o martelo ensanguentado nas mãos. O golem disse: \"SORTE SUA QUE NÃO ESCOLHEU A ESPADA\".","A espada era a Holy Avenger. O \"golem\" era ninguém menos que Mestre Arsenal, que estava lá para roubar os itens do mago."],"subtexto":"A noção de que pode haver confusão entre um golem e uma pessoa, e de que um assassino perigoso pode estar logo ao lado, reflete as substituições dos jovens nobres no último Baile da Primavera.","dica":"Aventura 6"},{"k":"dragoes","nome":"Existem Dragões nos Esgotos de Valkaria","texto":["Muitos aventureiros matam dragões, mas ficam com pena de destruir seus ovos. Eles então trazem os ovos de volta à cidade e tentam criar os dragões bebês, achando que eles poderão ser aliados fiéis e que, com bastante amor, não se tornarão malignos.","Mas dragões bebês são responsabilidade demais para aventureiros. Cuidar deles é muito caro e, mais cedo ou mais tarde, eles mostram seu lado maligno. Os aventureiros então jogam os dragõezinhos em bueiros, para que se afoguem ou sejam levados embora. Nos esgotos, eles têm contato com produtos alquímicos e todo tipo de dejetos. Ficam deformados e ainda mais ferozes que o normal.","Qualquer um pode ser pego por um deles, então repasse para todas as pessoas que você conhece."],"subtexto":"A lenda com o subtexto mais óbvio: os \"dragões do esgoto\" criados por Khenzarr.","dica":"Aventura 5"}],"aberturas":["Isso aconteceu com o primo de uma amiga minha, juro por Khalmyr.","Quem me contou foi o cunhado do taverneiro, e ele conhece a família.","Uma colega da guilda ouviu de um guarda que estava lá.","A vizinha da minha tia viu com os próprios olhos, não é boato.","O irmão de um aprendiz da Academia contou para o meu sócio.","Um amigo do meu amigo trabalha no Palácio, então é verdade."]};
(async function macroLenda(D) {
		const ESTADO = "fdtLendas";
		const est = foundry.utils.deepClone(game.user.getFlag("world", ESTADO) ?? {});
		est.contadas ??= [];
		const op = D.lendas.map((l, i) => `<option value="${i + 1}">${i + 1}. ${l.nome}${est.contadas.includes(l.k) ? " (já contada)" : ""}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Valkaria · Lenda Urbana" },
			position: { width: 500 },
			content: `
				<div class="form-group"><label>O que fazer</label><select name="acao">
					<option value="rolar">Rolar 1d6</option>
					<option value="escolher">Contar a lenda escolhida</option>
					<option value="colecao">Mostrar as lendas que o grupo já ouviu</option>
					<option value="zerar">Zerar a coleção</option></select></div>
				<div class="form-group"><label>Lenda</label><select name="n">${op}</select></div>
				<div class="form-group"><label>Quem conta</label><input type="text" name="quem" placeholder="o token selecionado, ou um nome"></div>
				<div class="form-group"><label>Como chega ao grupo</label><select name="meio">
					<option value="fala">Contada por alguém</option>
					<option value="escrita">Lida num diário ou anotação</option>
					<option value="gazeta">Publicada na Gazeta do Reinado</option></select></div>`,
			ok: { label: "Contar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const whisper = ChatMessage.getWhisperRecipients("GM");
		if (res.acao === "zerar") {
			await game.user.setFlag("world", ESTADO, { ...est, contadas: [] });
			return ChatMessage.create({ whisper, content: "<p>Lendas urbanas: coleção zerada.</p>" });
		}
		if (res.acao === "colecao") {
			const ja = D.lendas.filter((l) => est.contadas.includes(l.k));
			return ChatMessage.create({ content: `<h3>Lendas urbanas ouvidas</h3>${ja.length ? `<ul>${ja.map((l) => `<li>${l.nome}</li>`).join("")}</ul>` : "<p>Nenhuma ainda.</p>"}<p style="font-size:0.85em">${ja.length} de ${D.lendas.length}.</p>` });
		}
		const rolls = [];
		let n = Number(res.n) || 1;
		if (res.acao === "rolar") {
			const r = await new Roll("1d6").evaluate();
			rolls.push(r);
			n = r.total;
		}
		const l = D.lendas[n - 1];
		const quem = String(res.quem ?? "").trim() || canvas.tokens?.controlled.find((t) => t.actor?.type !== "character")?.name || "";
		let abre = "";
		if (res.meio === "fala") {
			const a = D.aberturas[Math.floor(Math.random() * D.aberturas.length)];
			abre = `<p><i>${quem ? `${quem}, baixando a voz:` : "Alguém baixa a voz:"} "${a}"</i></p>`;
		} else if (res.meio === "escrita") abre = "<p><i>Anotado às pressas, à margem de um diário:</i></p>";
		else abre = "<p><i>Gazeta do Reinado, página de curiosidades:</i></p>";
		await ChatMessage.create({ rolls, content: `<h3>${l.nome}</h3>${abre}${l.texto.map((t) => `<p>${t}</p>`).join("")}` });
		await ChatMessage.create({ whisper, content: `<p><b>Subtexto de ${l.nome}:</b> ${l.subtexto}</p><p style="font-size:0.85em">Dica de: ${l.dica}.</p>` });
		if (!est.contadas.includes(l.k)) est.contadas.push(l.k);
		await game.user.setFlag("world", ESTADO, est);
	})(DADOS);
